name: Check duplicate latestVersions logic

on:
  pull_request:
    branches: [main]
  push:
    branches: [main]

jobs:
  check-duplication:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Verify duplicate latestVersions logic
        run: |
          node <<'NODE'
          const fs = require('fs');
          const files = [
            'build-tools/packages/build-cli/src/commands/check/latestVersions.ts',
            'build-tools/packages/build-cli/src/commands/vnext/check/latestVersions.ts'
          ];

          const extractBlock = (content) => {
            const start = content.indexOf('const stableVersions');
            if (start === -1) return null;
            const endMarker = 'this.log(`##vso[task.setvariable variable=shouldDeploy]${shouldDeploy}`);';
            const end = content.indexOf(endMarker, start);
            if (end === -1) return null;
            return content.slice(start, end + endMarker.length);
          };

          const blocks = files.map(file => {
            const content = fs.readFileSync(file, 'utf8');
            const block = extractBlock(content);
            if (!block) {
              console.error(`Could not extract block from ${file}`);
              process.exit(1);
            }
            return block.trim();
          });

          if (blocks[0] !== blocks[1]) {
            console.error('Duplicate latestVersions logic differs between files.');
            process.exit(1);
          } else {
            console.log('Duplicate latestVersions logic is identical.');
          }
          NODE
